// One sheet row per new job. Column names must match the header row of your sheet
// (the Sheets node adds any missing columns on the first run).
const salary = (j) => {
  if (j.salaryMin == null && j.salaryMax == null) return '';
  const f = (n) => (n == null ? '?' : Math.round(n).toLocaleString('en-US'));
  return `${j.salaryCurrency ?? ''} ${f(j.salaryMin)}-${f(j.salaryMax)} per ${j.salaryPeriod ?? 'year'}`.trim();
};
return $input.all()
  .map((i) => i.json)
  .filter((j) => j.title && j.url)
  .map((j) => ({ json: {
    company: j.company ?? '',
    title: j.title,
    department: j.department ?? '',
    location: j.location ?? '',
    country: j.country ?? '',
    workplace: j.workplaceType ?? (j.remote ? 'remote' : ''),
    employmentType: j.employmentType ?? '',
    salary: salary(j),
    postedAt: j.postedAt ?? '',
    url: j.url,
    jobId: `${j.source ?? ''}:${j.jobId ?? j.url}`,
    foundAt: new Date().toISOString().slice(0, 10),
  } }));
